// GENERATED by scripts/sync-shared.mjs from the web app — do not edit; run `npm run sync:shared`.
import type { Config, Item, Scenario } from "../topicDraft/types";
import type { LoadoutMission } from "../topicDraft/formats/loadout";
import type { Role } from "../topicDraft/formats/position";
import type { QuizData } from "../topicDraft/trivia/types";

export type FormatId = "snake" | "spin" | "auction" | "loadout" | "position" | "blind" | "keep" | "feud" | "jeopardy" | "imposter" | "vote" | "insync" | "partytrivia" | "mafia" | "vowelplay" | "vowelparty";

/** Party games: online only, played on phones in one room. `pool` is a topic (Imposter) or a card deck (vote games). */
export const PARTY_FORMATS = new Set<FormatId>(["imposter", "vote", "insync", "partytrivia", "mafia", "vowelplay", "vowelparty"]);

export type Opts = {
  teamSize: number;
  order: "snake" | "linear";
  timerSeconds: number | null;
  useRoles: boolean;
  noDupUniverse: boolean;
  powerCap: number | null;
  bans: string[];
  universes: string[];
  customItems: Item[];
  // random roll (Spin Draft always rolls; Classic and Loadout can opt in)
  roll: boolean;
  options: number;
  rerolls: number;
  // quiz formats: question texts seen recently on this device, so new games prefer fresh ones
  avoid: string[];
  // judging: also duel every pick against the other team under the mission
  battle: boolean;
  // auction
  budget: number;
  lotSeconds: number;
  /** Blind lots: bid on a few clues about the item and find out who it is when it sells. */
  blind: boolean;
  clues: number;
  // position
  handExtra: number;
  // blind
  rankSize: number;
  /** Imposter: "guess" lets the imposter name the secret any time; "vote" leaves it to the vote. */
  ending: "guess" | "vote";
  /** Party games: sip cards on. Off by default. */
  drinking: boolean;
  /** Party games: show who voted what on the reveal. */
  showVotes: boolean;
  /** Party games: number of teams, 0 for none. */
  teams: number;
  /** Party games: player name to team index. */
  teamMap: Record<string, number>;
  /** Vowel Play: "first" takes the word for the first correct answer, "duel" is Head to head. */
  vowelMode: "first" | "duel";
  /** Vowel Play: say it aloud and let the others judge, or type it. */
  vowelAnswer: "voice" | "type";
};

export type GameSetup = {
  id: string;
  format: FormatId;
  pool: string;
  /** Party games: every topic or deck picked, in order. `pool` is `pools[0]`. Absent on older setups, which means `[pool]`. */
  pools?: string[];
  players: string[];
  aiPlayers: string[];
  mission: Scenario;
  mystery: boolean;
  loadout: LoadoutMission | null;
  roles: Role[];
  opts: Opts;
  /** Jeopardy and Family Feud: the questions for this game, chosen by the server so rooms share them. */
  quiz?: QuizData;
  seed: number;
};

/** The pool ids a setup draws from: its `pools`, or just `pool` for one-topic setups (and when `pool` was changed after, so it no longer leads `pools`). */
export const poolsOf = (setup: Pick<GameSetup, "pool" | "pools">): string[] => (setup.pools?.length && setup.pools[0] === setup.pool ? setup.pools : [setup.pool]);

export const DEFAULT_OPTS: Opts = {
  teamSize: 5,
  order: "snake",
  timerSeconds: 30,
  useRoles: false,
  noDupUniverse: false,
  powerCap: null,
  bans: [],
  universes: [],
  customItems: [],
  roll: false,
  battle: false,
  avoid: [],
  options: 3,
  rerolls: 1,
  budget: 20,
  lotSeconds: 15,
  blind: false,
  clues: 3,
  handExtra: 2,
  rankSize: 6,
  ending: "guess",
  drinking: false,
  showVotes: true,
  teams: 0,
  teamMap: {},
  vowelMode: "first",
  vowelAnswer: "voice",
};

export function snakeConfig(setup: GameSetup): Config {
  const o = setup.opts;
  return {
    teamSize: o.teamSize,
    players: setup.players,
    order: o.order,
    timerSeconds: o.timerSeconds,
    bans: o.bans,
    roles: o.useRoles ? ["Leader", "Tank", "Brain", "Striker", "Support", "Speedster", "Mystic", "Wildcard", "Backup"].slice(0, o.teamSize) : [],
    noDupUniverse: o.noDupUniverse,
    powerCap: o.powerCap,
    scenario: setup.mission.id,
    filters: { universes: o.universes },
  };
}
